// Runtime for the generated GharBasket API types (ADR-0022, ADR-0024). Reviewed by both app owners;
// src/generated/schema.d.ts is generated by `just gen-api` and never edited by hand.
import createFetchClient from "openapi-fetch";
import createQueryClient from "openapi-react-query";

/** @typedef {import("./generated/schema").paths} paths */
/** @typedef {import("./generated/schema").components["schemas"]} schemas */

const STANDARD_MEMBERS = new Set([
  "type",
  "title",
  "status",
  "detail",
  "code",
  "instance",
  "request_id",
  "errors",
]);

/** An RFC 9457 problem+json response. Branch on `code`, never on `status` or the text. */
export class ApiProblem extends Error {
  /**
   * @param {number} status
   * @param {Record<string, unknown>} body the parsed problem (or {} when the body was not JSON)
   */
  constructor(status, body) {
    const code = typeof body.code === "string" ? body.code : `http.${status}`;
    super(typeof body.detail === "string" ? body.detail : code);
    this.name = "ApiProblem";
    this.status = status;
    this.code = code;
    /** Extension members, e.g. `household_id` on identity.household_exists. */
    this.extra = Object.fromEntries(
      Object.entries(body).filter(([key]) => !STANDARD_MEMBERS.has(key)),
    );
    /** Field errors of `request.invalid` (422). */
    this.errors = Array.isArray(body.errors) ? body.errors : [];
    this.requestId = typeof body.request_id === "string" ? body.request_id : null;
  }
}

/**
 * @typedef {object} ApiOptions
 * @property {string} [baseUrl] API origin; "" (same origin, through the Vercel /v1 rewrite) by default
 * @property {boolean} [web] browsers: send cookies and `X-GB-Client: web` instead of a Bearer token
 * @property {() => string | null | undefined} [getAccessToken] apps: the current access token
 * @property {() => string | null | undefined} [getActiveRole] optional `X-Active-Role`, e.g. "captain:<id>"
 * @property {typeof fetch} [fetch] for tests
 */

/** @param {ApiOptions} [options] */
export function createApi(options = {}) {
  const { baseUrl = "", web = false, getAccessToken, getActiveRole } = options;
  /** @type {import("openapi-fetch").Client<paths>} */
  const client = createFetchClient({
    baseUrl,
    credentials: web ? "include" : "omit",
    ...(options.fetch ? { fetch: options.fetch } : {}),
  });
  client.use({
    onRequest({ request }) {
      if (web) {
        request.headers.set("X-GB-Client", "web");
      } else {
        const token = getAccessToken?.();
        if (token) request.headers.set("Authorization", `Bearer ${token}`);
      }
      const role = getActiveRole?.();
      if (role) request.headers.set("X-Active-Role", role);
      return request;
    },
  });

  return {
    client,
    /** React Query hooks: `$query.useQuery("get", "/v1/households/me")`. Errors are the problem body. */
    $query: createQueryClient(client),
    /**
     * The data of an openapi-fetch call, or throw ApiProblem.
     * @template T
     * @param {Promise<{ data?: T, error?: unknown, response: Response }>} call
     * @returns {Promise<T>}
     */
    async unwrap(call) {
      const { data, error, response } = await call;
      if (!response.ok) {
        const body = error && typeof error === "object" ? error : {};
        throw new ApiProblem(response.status, /** @type {Record<string, unknown>} */ (body));
      }
      return /** @type {T} */ (data);
    },
  };
}

/** A fresh Idempotency-Key: one per user intent, reused for retries of that same request. */
export function newIdempotencyKey() {
  return crypto.randomUUID();
}
